data class Task(val id: Int, val title: String)

fun main() {
    val table = mutableMapOf<Int, Task>()
    fun insertReplace(t: Task) { table[t.id] = t }
    fun insertIgnore(t: Task) { table.putIfAbsent(t.id, t) }
    insertReplace(Task(1, "хлеб"))
    insertReplace(Task(1, "сыр"))
    insertIgnore(Task(1, "мёд"))
    insertIgnore(Task(2, "чай"))
    println(table.values.map { it.title })
    println(table.size)
}
